// --- Types and Interfaces ---

type TerrainType = 'Vines' | 'Biomass' | 'Clear' | 'HabitableZone';

interface MapCell {
  terrain: TerrainType;
  entities: Set<string>;
  biomassLevel: number; // New: 0-100
  isCleared: boolean; // New: Tracks if biomass has been cleared
}

export class WorldMap {
  private cells: Map<string, MapCell> = new Map();

  /**
   * Gets the key for a given coordinate.
   * @param x The x-coordinate.
   * @param y The y-coordinate.
   * @returns The coordinate key string.
   */
  private getCellKey(x: number, y: number): string {
    return `${x},${y}`;
  }

  /**
   * Sets the terrain for a given coordinate.
   * @param x The x-coordinate.
   * @param y The y-coordinate.
   * @param terrain The terrain type.
   */
  public setTerrain(x: number, y: number, terrain: TerrainType): void {
    const key = this.getCellKey(x, y);
    if (!this.cells.has(key)) {
      // Initialize new cell with default biomass/cleared state
      this.cells.set(key, { terrain: terrain, entities: new Set(), biomassLevel: terrain === 'Biomass' ? 100 : 0, isCleared: false });
    } else {
      const cell = this.cells.get(key)!;
      cell.terrain = terrain;
    }
  }

  /**
   * Gets the terrain for a given coordinate.
   * @param x The x-coordinate.
   * @param y The y-coordinate.
   * @returns The terrain type or undefined if not set.
   */
  public getTerrain(x: number, y: number): TerrainType | undefined {
    return this.cells.get(this.getCellKey(x, y))?.terrain;
  }

  // --- New methods for biomass tracking ---

  public getCell(x: number, y: number): MapCell | undefined {
    return this.cells.get(this.getCellKey(x, y));
  }

  public getBiomassLevel(x: number, y: number): number | undefined {
    return this.cells.get(this.getCellKey(x, y))?.biomassLevel;
  }

  public setBiomassLevel(x: number, y: number, level: number): void {
    const key = this.getCellKey(x, y);
    const cell = this.cells.get(key);
    if (cell) {
      cell.biomassLevel = Math.max(0, Math.min(100, level));
    }
  }

  public setClearedStatus(x: number, y: number, cleared: boolean): void {
    const key = this.getCellKey(x, y);
    const cell = this.cells.get(key);
    if (cell) {
      cell.isCleared = cleared;
    }
  }
}
